"""Bounded tmSUM/tmSUMOP variant repair, grounded in user supplied previews.

Equation-only MTEF payloads come from two local test documents. Whole documents
are not distributed. Their original WMF uses TA_UPDATECP: upper n baselines are
261/253, sum glyph baselines 740/749, lower m=k+1/k=1 baselines 1018/1027.
The SDK's older slot table is not used as proof of this 0x70 variant's order.
"""
from mathbank.mtef_helper import MtefNode, _render_template, decode_mtef_formula
import pytest

SOURCE_CASES = [
    (bytes.fromhex(''), 'g_{k}=\\dfrac{1}{n}\\times k+\\dfrac{1}{n}\\left(1-g_{k+1}\\right)+\\dfrac{1}{n}\\left(1-g_{k+2}\\right)+\\cdots+\\dfrac{1}{n}\\left(1-g_{n}\\right)=1-\\dfrac{1}{n}\\sum_{m=k+1}^{n}{g_{m}}'),
    (bytes.fromhex(''), '\\sum_{k=1}^{n}\\left(\\sqrt{tan\\dfrac{\\pi}{4^{k}}}+\\sqrt{sin\\dfrac{\\pi}{4^{k}}}\\right)>2\\sum_{k=1}^{n}\\sqrt{\\dfrac{\\pi}{4^{k}}}=\\sum_{k=1}^{n}\\dfrac{2\\sqrt{\\pi}}{2^{k}}=2\\sqrt{\\pi}\\left(1-\\dfrac{1}{2^{n}}\\right)'),

]

@pytest.mark.parametrize("payload,expected", SOURCE_CASES)
def test_actual_0x70_limits_match_original_wmf_not_old_inverted_output(payload, expected):
    result = decode_mtef_formula(payload)
    assert result.success and result.confidence == "structural" and result.latex == expected
    assert result.ignored_spacing_codes == ("U+EF0A",) and not result.warning
    assert r"\sum_{n}^{k=1}" not in result.latex and r"\sum_{n}^{m=k+1}" not in result.latex


def line(text):
    return MtefNode("line", children=[MtefNode("char", {"mtcode": ord(c), "typeface": 3}) for c in text])


@pytest.mark.parametrize("selector", [16, 22])
def test_unproved_0x03_variant_keeps_its_existing_upper_then_lower_contract(selector):
    node = MtefNode("template", {"selector": selector, "variation": 3, "template_options": 0},
                    [line("x"), line("n"), line("k=1"), line("")])
    # The generic selector needs its explicitly supplied operator.
    node.children[-1] = MtefNode("char", {"mtcode": 0x2211, "typeface": 6})
    assert _render_template(node) == r"\sum_{k=1}^{n}{x}"


@pytest.mark.parametrize("selector", [15, 17, 18, 19, 20, 21])
def test_0x70_does_not_authorize_other_big_operator_template_classes(selector):
    node = MtefNode("template", {"selector": selector, "variation": 0x70, "template_options": 0},
                    [line("x"), line("n"), line("k=1"), MtefNode("char", {"mtcode": 0x2211, "typeface": 6})])
    assert _render_template(node) == r"\sum_{k=1}^{n}{x}"


@pytest.mark.parametrize("selector", [16, 22])
def test_unknown_template_options_do_not_acquire_variant_authority(selector):
    node = MtefNode("template", {"selector": selector, "variation": 0x70, "template_options": 1},
                    [line("x"), line("n"), line("k=1"), MtefNode("char", {"mtcode": 0x2211, "typeface": 6})])
    assert _render_template(node) == r"\sum_{k=1}^{n}{x}"
